{"path": "tests/test_search.py", "file_text": "import pytest
from app.api.handlers import handle_search_users

def test_search_users_valid():
    params = {"q": "Ada"}
    status, result = handle_search_users(params)
    assert status == 200
    assert len(result["users"]) == 1
    assert result["users"][0]["name"] == "Ada"

def test_search_users_case_insensitive():
    params = {"q": "ada"}
    status, result = handle_search_users(params)
    assert status == 200
    assert len(result["users"]) == 1
    assert result["users"][0]["name"] == "Ada"

def test_search_users_email():
    params = {"q": "linus@"}
    status, result = handle_search_users(params)
    assert status == 200
    assert len(result["users"]) == 1
    assert result["users"][0]["name"] == "Linus"

def test_search_users_invalid_query():
    assert handle_search_users({"q": ""}) == (400, {"error": "invalid query"})
    assert handle_search_users({"q": "   "}) == (400, {"error": "invalid query"})
    assert handle_search_users({}) == (400, {"error": "invalid query"})
    assert handle_search_users({"q": 123}) == (400, {"error": "invalid query"})
"}

